package vn.codegym;import java.sql.*;import java.util.*;public class ProductDao{private Connection open()throws SQLException{return DriverManager.getConnection("jdbc:mysql://localhost:3306/final_exam",System.getenv().getOrDefault("DB_USER","root"),System.getenv().getOrDefault("DB_PASSWORD",""));}public List<Product> all()throws SQLException{List<Product> x=new ArrayList<>();try(Connection c=open();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM products")){while(r.next())x.add(new Product(r.getInt(1),r.getString(2),r.getDouble(3),r.getInt(4)));}return x;}public void save(Product x)throws SQLException{String q=x.id()==0?"INSERT INTO products(name,price,quantity) VALUES(?,?,?)":"UPDATE products SET name=?,price=?,quantity=? WHERE id=?";try(Connection c=open();PreparedStatement p=c.prepareStatement(q)){p.setString(1,x.name());p.setDouble(2,x.price());p.setInt(3,x.quantity());if(x.id()!=0)p.setInt(4,x.id());p.executeUpdate();}}public void delete(int id)throws SQLException{try(Connection c=open();PreparedStatement p=c.prepareStatement("DELETE FROM products WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}}
